function Picker({value,onChange,options,label,className="",disabled=false}:{value:string;onChange:(v:string)=>void;options:{value:string;label:string}[];label:string;className?:string;disabled?:boolean}) {
 return <Select value={value} onValueChange={next=>{if(options.some(option=>option.value===next))onChange(next);}} disabled={disabled}><SelectTrigger aria-label={label} className={`app-select ${className}`}><SelectValue>{options.find(option=>option.value===value)?.label||"選択してください"}</SelectValue></SelectTrigger><SelectContent position="popper">{options.map(o=><SelectItem key={o.value} value={o.value}>{o.label}</SelectItem>)}</SelectContent></Select>;
}

function useWriteRetry<T>() {
 const [saving,setSaving]=useState(false);
 const [pending,setPending]=useState<T|null>(null);
 const [error,setError]=useState("");
 const operation=useRef(crypto.randomUUID());
 const reset=()=>{operation.current=crypto.randomUUID();setPending(null);setError("");};
 const run=async(value:T,save:(value:T,id:string)=>Promise<unknown>)=>{
  if(saving)return false;
  const payload=pending||value;setPending(payload);setSaving(true);setError("");
  try{await save(payload,operation.current);setPending(null);return true;}
  catch(e){if(!isUncertainWrite(e))reset();setError(e instanceof Error?e.message:"保存できませんでした。");return false;}
  finally{setSaving(false);}
 };
 return {saving,pending,error,reset,run};
}
function InsupLogo({className="",decorative=false}:{className?:string;decorative?:boolean}){return <img className={`insup-logo ${className}`} src={`${import.meta.env.BASE_URL}insup-logo-transparent.png`} alt={decorative?"":"Insup"} width={1226} height={1283}/>;}
function Avatar({player,small=false}:{player:Player;small?:boolean}){return <span className={`avatar ${player.color} ${small?"small-avatar":""}`}>{player.name.slice(0,1)}</span>}

