 const [targetSwitch,setTargetSwitch]=useState<{label:string;change:()=>void}|null>(null);
 const requestTargetSwitch=(label:string,change:()=>void)=>{if(saving||pending.current)return;if(closeGuard.dirty){setTargetSwitch({label,change});return;}change();};
