 {admin&&<label>担当者<Picker label="担当者" value={owner} onChange={v=>requestTargetSwitch("担当者",()=>{setOwner(v);setCandidate(null);resetTarget();})} options={players.map(p=>({value:p.id,label:p.name}))}/></label>}
